package com.gymmind.knowledge.infrastructure.search; import java.util.List; public interface KeywordIndexPort { void upsert(IndexedChunk chunk); List<IndexedChunk> search(String query,Long tenantId); default List<IndexedChunk> search(String query,Long tenantId,Long userId){return search(query,tenantId).stream().filter(c->c.visibleTo(userId)).toList();} void delete(String id,Long tenantId); }
